public List<Customer> findByCity(Connection conn, String city) throws SQLException {
    Statement st = conn.createStatement();
    ResultSet rs = st.executeQuery("SELECT id, name, email FROM customers WHERE city = '" + city + "'");
    List<Customer> out = new ArrayList<>();
    while (rs.next()) {
        out.add(new Customer(rs.getLong("id"), rs.getString("name"), rs.getString("email")));
    }
    return out;
}

