pub fn read_u16(buf: &[u8], offset: usize) -> u16 {
    unsafe {
        let lo = *buf.get_unchecked(offset) as u16;
        let hi = *buf.get_unchecked(offset + 1) as u16;
        lo | (hi << 8)
    }
}

